import java.util.*;
import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        List<Long>[] data = new ArrayList[11];
        for (int i = 0; i <= 10; i++) {
            data[i] = new ArrayList<>();
        }
        long[] total = new long[11];
        final long MOD1 = 998244353;
        final long MOD2 = 1000000007;
        long count = 0;
        long tmp_count = 0;
        long res = 0;

        Function<Long, Long> mod_func = (Long x) -> ((x % MOD1) + MOD1) % MOD1;

        // build1 function
        BiConsumer<Integer, Long> build1 = new BiConsumer<Integer, Long>() {
            @Override
            public void accept(Integer level, Long val) {
                if (val > n) return;
                if (level > 6) return;
                count++;
                long v = mod_func.apply(count - val);
                data[level].add(v);
                total[level] += v;
                for (int d = 0; d <= 9; d++) {
                    accept(level + 1, val * 10 + d);
                }
            }
        };

        // build2 function
        BiConsumer<Integer, Long> build2 = new BiConsumer<Integer, Long>() {
            @Override
            public void accept(Integer level, Long val) {
                if (val > n) return;
                if (level >= 1) {
                    if (val * 10 * n > n && val * n + n - 1 <= n) {
                        for (int i = 0; i <= 6; i++) {
                            long v = mod_func.apply(count - val);
                            List<Long> vec = data[i];
                            int pos = lowerBound(vec, MOD1 - v);
                            res = (res + v * (long) vec.size() + total[i] - MOD1 * ((long) vec.size() - pos)) % MOD2;
                        }
                        count += tmp_count;
                        return;
                    }
                    count++;
                    res = (res + mod_func.apply(count - val)) % MOD2;
                }
                int startD = (level == 0) ? 1 : 0;
                for (int d = startD; d <= 9; d++) {
                    accept(level + 1, val * 10 + d);
                }
            }
        };

        // Build1
        build1.accept(0, 0L);
        tmp_count = count;
        count = 0;

        for (int i = 0; i <= 6; i++) {
            Collections.sort(data[i]);
        }

        // Build2
        build2.accept(0, 0L);

        System.out.println(res);
        sc.close();
    }

    // Helper method for lower_bound
    private static int lowerBound(List<Long> list, long key) {
        int low = 0;
        int high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}
